/* Browser-local planning and review tools. No feedback is transmitted. */
const TEACHING_WORDS={5:['am','at','mat'],10:['sit','pin','map'],11:['ham','man','pan'],19:['cat','pig','dog'],35:['cat','map','ham'],36:['sit','pin','fin'],37:['dog','mop','pot'],38:['cat','sit','mop'],39:['bug','cup','sun'],40:['pet','hen','bed'],41:['cat','pig','bug'],42:['puff','bell','miss'],43:['ball','roll','pull'],44:['back','duck','sock'],45:['ship','shop','fish'],46:['this','that','them'],47:['thin','bath','moth'],48:['chip','chat','much'],49:['ship','chip','duck'],50:['whip','when','graph'],51:['sing','ring','song'],52:['sink','bank','pink'],54:['cake','gate','name'],55:['bike','time','five'],56:['home','rope','hope'],58:['cube','mule','rule'],59:['cake','bike','home'],64:['jumped','played','rested'],65:['helping','jumping','resting'],69:['catch','match','fetch'],70:['badge','edge','fudge'],71:['catch','badge','match'],73:['my','by','fly'],74:['happy','sunny','funny'],75:['table','little','candle'],77:['car','star','park'],78:['corn','fork','more'],80:['her','fern','term'],81:['bird','turn','shirt'],84:['rain','play','train'],85:['see','team','key'],86:['boat','snow','toe'],87:['pie','night','light'],89:['book','look','put'],90:['moon','zoo','food'],91:['blue','fruit','new'],93:['saw','paw','haul'],94:['head','bread','wash'],95:['coin','toy','boy'],96:['out','cow','town'],98:['knee','write','lamb'],99:['cats','dogs','boxes'],100:['faster','fastest','taller'],101:['slowly','softly','quickly'],102:['helpful','hopeless','careful'],103:['undo','unpack','unfair'],104:['redo','reread','preheat'],105:['dislike','disagree','disconnect'],107:['hopped','hopping','running'],109:['making','hoping','riding'],110:['cried','tries','happier'],112:['air','care','bear'],113:['ear','hear','near'],119:['action','station','mission'],120:['picture','nature','future'],122:['smallish','greenish','childish'],123:['rainy','windy','dusty'],124:['kindness','sadness','darkness'],125:['payment','enjoyment','movement'],126:['readable','washable','visible'],127:['unicycle','bicycle','tricycle']};
let face='teacher',kidStep='start',kidWord=0,kidBlended=false,assignedVideo=null;
function localReviews(){const v=read('reviews',{});return v&&typeof v==='object'&&!Array.isArray(v)?v:{}}
function preferredVideo(n){const ids={45:'4m-sh',47:'4m-th',48:'4m-ch',52:'4m-nk',54:'4m-a-e',55:'4m-i-e',56:'4m-o-e',58:'4m-u-e',64:'4m-ed-d',84:'4m-ai',89:'4m-oo-short',90:'4m-oo-long',95:'4m-oi',96:'4m-ou'};const reviews=localReviews();const explicitlyAssigned=VIDEOS.find(v=>v.id===assignedVideo&&supportsLesson(v,n));if(explicitlyAssigned)return explicitlyAssigned;const candidates=VIDEOS.filter(v=>supportsLesson(v,n)&&!['advanced','broken'].includes(reviews[v.id]?.rating));return candidates.find(v=>v.id===ids[n])||candidates.find(v=>v.lesson===n&&(v.lessons?.length||1)===1)||candidates.find(v=>v.lesson===n)||candidates[0]}
function lessonURL(n,child=false,id=null){const u=new URL(location.href);u.hash=new URLSearchParams({lesson:String(n),face:child?'home':'teacher',...(id?{video:id}:{})}).toString();return u.href}
async function copyLesson(n,child=false,id=null){const link=lessonURL(n,child,id);try{await navigator.clipboard.writeText(link);toast(location.hostname==='127.0.0.1'||location.hostname==='localhost'?'Local preview link copied. It works on this computer.':child?'Home-learning link copied.':'Lesson link copied.')}catch{const el=$('#share-link');if(el){el.value=link;el.focus();el.select();toast('Link selected. Copy it to share.')}else toast('Copy this page’s address to share the lesson.')}}
function goLesson(n,update=true){if(!Number.isInteger(n)||n<1||n>128){toast('Choose a lesson from 1 to 128.');return}selectedLesson=n;view='home';category='all';query='';$('#search').value='';$('#lesson-number').value=n;if(update)window.history.replaceState(null,'',lessonURL(n,face==='home',assignedVideo));kidStep='start';kidWord=0;render();if(face==='teacher')$('#lesson-workspace').scrollIntoView({behavior:'smooth',block:'start'})}
function setFace(next){face=next;document.body.dataset.face=face;$('#teacher-face').setAttribute('aria-pressed',face==='teacher');$('#home-face').setAttribute('aria-pressed',face==='home');if(face==='home'&&!selectedLesson)selectedLesson=45;if(selectedLesson)window.history.replaceState(null,'',lessonURL(selectedLesson,face==='home',assignedVideo));render();window.scrollTo({top:0,behavior:'smooth'})}
function renderTeacherWorkspace(){document.body.dataset.face=face;$('#hero').hidden=face==='home'||view!=='home'||!!selectedLesson||Boolean(query.trim());$('#quick-start').hidden=face==='home'||view!=='home'||!!selectedLesson||Boolean(query.trim());const panel=$('#lesson-workspace');panel.hidden=face==='home'||!selectedLesson;if(face==='home'){renderKid();return}$('#kid-shell').hidden=true;if(!selectedLesson)return;const n=selectedLesson,v=preferredVideo(n),words=TEACHING_WORDS[n];const review=v?localReviews()[v.id]:null;panel.innerHTML=`<div class="lesson-top"><button id="back-library" class="back-link">All discoveries</button><span class="mini-label">YOUR LESSON, READY TO GO</span><div class="lesson-share"><button class="secondary" id="share-teacher"><i data-icon="stack"></i> Copy teacher link</button><button class="primary" id="share-home"><i data-icon="heart"></i> Share home learning</button></div></div><div class="lesson-heading"><div><span class="lesson-number-pill">UFLI · LESSON ${n}</span><h1>${esc(LESSON_NAMES[n-1])}</h1><p>A clear starting point. A little practice. One more confident reader.</p></div><button class="kid-preview" id="preview-home"><span>✦</span> Preview the child’s view</button></div><div class="lesson-plan-grid"><article class="suggestion"><div class="suggestion-label"><span>✦ SUGGESTED STARTING POINT</span><span>Preview before assigning</span></div>${v?`<button class="suggestion-art" data-open="${v.id}" style="--tone:${tones[v.tone]}"><span>${esc(v.sound)}</span><b class="big-play">▶</b><small>${time(v.seconds)}</small></button><div class="suggestion-details"><h2>${esc(v.title)}</h2><p>${esc(v.creator)}</p><div class="resource-flags"><span>${time(v.seconds)}</span><span>${esc(v.accent||'Check pronunciation')}</span><span class="ad-label">YouTube · ads may appear</span></div><p class="teaching-note">${esc(v.note)}</p><div class="suggestion-actions"><button class="primary" data-open="${v.id}"><i data-icon="play"></i> Preview video</button><button class="secondary" id="choose-home">Use for home learning</button></div><div class="review-tools"><b>Your preview notes</b><span>Saved on this device</span><div>${[['fit','Good fit'],['advanced','Too advanced'],['broken','Link issue']].map(([key,label])=>`<button data-review="${key}" data-id="${v.id}" aria-pressed="${review?.rating===key}">${label}</button>`).join('')}</div><button id="export-reviews" class="plain-link">Export team review notes</button></div></div>`:`<div class="suggestion-details no-video"><span>✦</span><h2>Practice comes first here.</h2><p>We haven’t found a short video limited to the letters taught so far. The built-in word practice is a better match.</p><button class="primary" id="lesson-practice">Open word practice</button></div>`}</article><aside class="after-watch"><span class="mini-label">THEN, TWO MINUTES TOGETHER</span><h2>Watch a little.<br>Make it stick.</h2><ol><li><span>1</span><div><b>Say it</b><p>Model the sound or word part. Invite children to repeat.</p></div></li><li><span>2</span><div><b>Read it</b><p>${words?'Blend these familiar words together:':'Choose three familiar words from your current classroom lesson.'}</p>${words?`<div class="word-pills">${words.map(w=>`<span>${esc(w)}</span>`).join('')}</div>`:''}</div></li><li><span>3</span><div><b>Write it</b><p>${words?'Say “'+esc(words[0])+'”. Stretch the sounds and write it together.':'Say one of those words. Stretch its sounds and write it together.'}</p></div></li><li><span>✦</span><div><b>Notice the little win</b><p>“You listened to every sound. That helped you read the word.”</p></div></li></ol><p class="practice-caution">Original practice suggestions. Preview the words for your group.</p><button class="secondary" id="print-lesson">Print lesson routine</button></aside></div><div class="share-bar"><span><b>A little learning, ready to send.</b><small>Home links open a calm child view with this lesson.</small></span><input id="share-link" aria-label="Home-learning lesson link" readonly value="${esc(lessonURL(n,true,v?.id))}"><button id="copy-home-link" class="secondary">Copy link</button></div>`;panel.onclick=e=>{const open=e.target.closest('[data-open]');if(open)openResource(open.dataset.open);const r=e.target.closest('[data-review]');if(r){const data=localReviews();data[r.dataset.id]={rating:r.dataset.review,lesson:n,updatedAt:new Date().toISOString()};write('reviews',data);toast('Your note is saved on this device.');render()}if(e.target.closest('#export-reviews'))exportReviews()};$('#back-library').onclick=()=>navigate('home');$('#share-teacher').onclick=()=>copyLesson(n,false,v?.id);$('#share-home').onclick=()=>copyLesson(n,true,v?.id);$('#copy-home-link').onclick=()=>copyLesson(n,true,v?.id);$('#preview-home').onclick=()=>{assignedVideo=v?.id||null;setFace('home')};if(v)$('#choose-home').onclick=()=>{assignedVideo=v.id;copyLesson(n,true,v.id)};if($('#lesson-practice'))$('#lesson-practice').onclick=()=>openResource(PRACTICE.find(p=>supportsLesson(p,n))?.id||PRACTICE[0].id);$('#print-lesson').onclick=()=>{document.body.classList.add('print-lesson');window.print();document.body.classList.remove('print-lesson')};icons()}
function exportReviews(){const records=Object.entries(localReviews()).map(([id,r])=>({videoId:id,title:VIDEOS.find(v=>v.id===id)?.title||id,...r}));if(!records.length){toast('Preview a video and add a note first.');return}const blob=new Blob([JSON.stringify({library:'Phonics Tube',exportedAt:new Date().toISOString(),reviews:records},null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='phonics-tube-team-review.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);toast('Review notes exported for your team.')}
function renderKid(){const n=selectedLesson||45,v=preferredVideo(n),words=TEACHING_WORDS[n]||[],focus=(v?.sound||LESSON_NAMES[n-1]).split(' /')[0];const shell=$('#kid-shell');shell.hidden=false;shell.innerHTML=`<header class="kid-header"><a class="brand" href="#"><span class="brand-mark">▶</span><span>phonics<span class="brand-light">tube</span><span class="brand-dot">.</span></span></a><span class="kid-home-label">A LITTLE LEARNING AT HOME</span><button id="kid-grownups">For grown-ups <i data-icon="heart"></i></button></header><main class="kid-main"><div class="kid-intro"><span class="kid-lesson">YOUR LITTLE ADVENTURE · LESSON ${n}</span><h1>${kidStep==='done'?'Look at you grow.':kidStep==='read'?'Let’s read together.':'Hello, little sound explorer.'}</h1><p>${kidStep==='done'?'A little practice. A very big high five.':kidStep==='read'?'Take your time. Your grown-up can help.':'One sound. A few words. A little more confident.'}</p></div><div class="kid-progress" aria-label="Learning steps"><span class="${kidStep==='start'?'current':'complete'}">1 <b>Meet the sound</b></span><i></i><span class="${kidStep==='read'?'current':kidStep==='done'?'complete':''}">2 <b>Try together</b></span><i></i><span class="${kidStep==='done'?'current':''}">✦ <b>Little win</b></span></div>${kidStep==='start'?`<section class="kid-adventure"><div class="kid-sound-stage"><span class="kid-spark">✦</span><div class="kid-sound-face"><strong>${esc(focus)}</strong><div class="friend-eyes"><b></b><b></b></div><div class="friend-smile"></div></div><span class="kid-tiny-star">✧</span><span class="kid-focus-caption">${esc(LESSON_NAMES[n-1])}</span></div><div class="kid-adventure-copy"><span class="mini-label">LET’S MEET TODAY’S SOUND</span><h2>Small sound.<br>Big adventure.</h2><p>Find your grown-up. Get comfy.<br>Let’s discover something together.</p>${v?`<button id="kid-watch" class="primary"><i data-icon="play"></i> Watch together <span>${time(v.seconds)}</span></button><small class="kid-adult-note">Grown-ups: preview first. YouTube may show ads.</small>`:`<p class="kid-adult-note">Today we’ll practise with your grown-up, without a video.</p>`}<button id="kid-read" class="secondary">${v?'Ready? Let’s try some words':'Let’s practise together'}</button></div></section>`:kidStep==='read'?`<section class="kid-read-stage"><span class="mini-label">${words.length?'WORD '+(kidWord+1)+' OF '+words.length:'SAY IT TOGETHER'}</span><div class="kid-practice-word">${esc(words.length?words[kidWord]:focus)}</div><p>${words.length?'Look at each part. Say the sounds, then blend the word.':'Ask your grown-up to model today’s sound. Try it together.'}</p><div class="kid-read-controls"><button id="kid-word-back" class="secondary" ${!words.length||kidWord===0?'disabled':''}>Previous word</button><button id="kid-next" class="primary">${!words.length||kidWord===words.length-1?'I tried it!':'Next word'}</button></div><small>Your grown-up can help you hear and blend the sounds.</small></section>`:`<section class="kid-celebrate"><div class="celebration-sun">✦</div><h2>You gave it a go.<br>That’s how readers grow.</h2><p>Tell your grown-up one thing you discovered today.</p><div class="word-pills">${words.map(w=>`<span>${esc(w)}</span>`).join('')}</div><button id="kid-again" class="primary">Try our little adventure again</button><p class="kid-close-note">Or close this page and carry on with your day. Well done, you.</p></section>`}<footer class="kid-footer"><span>Small moments. Big breakthroughs.</span><button id="kid-help">A little help for grown-ups</button></footer></main>`;$('#kid-grownups').onclick=()=>setFace('teacher');$('#kid-help').onclick=()=>$('#guide').showModal();shell.querySelector('.brand').onclick=e=>{e.preventDefault();kidStep='start';renderKid()};if($('#kid-watch'))$('#kid-watch').onclick=()=>openResource(v.id);if($('#kid-read'))$('#kid-read').onclick=()=>{kidStep='read';kidWord=0;renderKid();icons()};if($('#kid-next'))$('#kid-next').onclick=()=>{if(kidWord<words.length-1)kidWord++;else kidStep='done';renderKid();icons()};if($('#kid-word-back'))$('#kid-word-back').onclick=()=>{if(kidWord>0)kidWord--;renderKid();icons()};if($('#kid-again'))$('#kid-again').onclick=()=>{kidStep='start';kidWord=0;renderKid();icons()};icons()}
function renderKidVideo(){const v=active;$('#dialog-kicker').textContent='WATCH TOGETHER · LESSON '+selectedLesson;$('#player-body').innerHTML=`<div class="player-content kid-video"><div class="video-placeholder"><span class="big-sound">${esc(v.sound)}</span><h2>A little discovery, together.</h2><p>Grown-ups: this video uses YouTube and may show ads. Please preview it before your child watches.</p><button class="primary" id="load-kid-video"><i data-icon="play"></i> Start with a grown-up</button></div><h2>${esc(v.title)}</h2><p>${esc(v.creator)} · ${time(v.seconds)} · ${esc(v.accent||'Preview pronunciation')}</p><button class="primary" id="kid-finish-watch">Now let’s try together</button></div>`;$('#load-kid-video').onclick=()=>{const iframe=document.createElement('iframe');iframe.className='video-frame';iframe.title=v.title;iframe.src='https://www.youtube-nocookie.com/embed/'+v.youtube+'?rel=0';iframe.allow='encrypted-media; picture-in-picture; fullscreen';iframe.allowFullscreen=true;$('.video-placeholder').replaceWith(iframe)};$('#kid-finish-watch').onclick=()=>{$('#player').close();kidStep='read';kidWord=0;renderKid()};icons()}
function initTeacherTools(){const hash=new URLSearchParams(location.hash.slice(1));const n=Number(hash.get('lesson'));face=hash.get('face')==='home'?'home':'teacher';assignedVideo=hash.get('video');if(n>=1&&n<=128){selectedLesson=n;$('#lesson-number').value=n}$('#lesson-finder').onsubmit=e=>{e.preventDefault();assignedVideo=null;goLesson(Number($('#lesson-number').value))};$$('[data-go-lesson]').forEach(b=>b.onclick=()=>goLesson(+b.dataset.goLesson));$('#quick-practice').onclick=()=>openResource(PRACTICE[0].id);$('#teacher-guide').onclick=()=>$('#guide').showModal();$('#print-guide').onclick=()=>{document.body.classList.add('print-guide');window.print();document.body.classList.remove('print-guide')};$('#teacher-face').onclick=()=>setFace('teacher');$('#home-face').onclick=()=>setFace('home');$('#teacher-face').setAttribute('aria-pressed',face==='teacher');$('#home-face').setAttribute('aria-pressed',face==='home');if(face==='home'&&!selectedLesson)selectedLesson=45;render()}

